import json, math
from pyscipopt import Model, quicksum
EARTH_RADIUS_MILES=3960.0
with open('/root/data.json') as f: data=json.load(f)
stations=data['stations']; ids=[s['id'] for s in stations]; byid={s['id']:s for s in stations}; vehicles=list(range(1,data['vehicle_count']+1)); cap=data['vehicle_capacity']; start='depot_start'; end='depot_end'; n=len(ids)
def coords(i):
    s=data['depot'] if i in (start,end) else byid[i]
    return s['latitude'],s['longitude']
def dist(i,j):
    a,b=map(math.radians,coords(i)); c,d=map(math.radians,coords(j))
    h=math.sin((c-a)/2)**2+math.cos(a)*math.cos(c)*math.sin((d-b)/2)**2
    return 2*EARTH_RADIUS_MILES*math.asin(math.sqrt(h))
arcs=[(i,j) for i in [start,*ids] for j in [*ids,end] if i!=j and not(i==start and j==end)]
m=Model('bike_rebalance'); m.hideOutput(); m.setParam('limits/time',300.0); M=3*cap
x={(k,i,j):m.addVar(vtype='B') for k in vehicles for i,j in arcs}
y={(k,i):m.addVar(vtype='B') for k in vehicles for i in ids}
u={(k,i):m.addVar(lb=0,ub=n) for k in vehicles for i in ids}
p={(k,i):m.addVar(vtype='I',lb=0,ub=max(0,byid[i]['net_rebalancing_target'])) for k in vehicles for i in ids}
d={(k,i):m.addVar(vtype='I',lb=0,ub=max(0,-byid[i]['net_rebalancing_target'])) for k in vehicles for i in ids}
l={(k,i):m.addVar(vtype='I',lb=0,ub=cap) for k in vehicles for i in ids}
sl={k:m.addVar(vtype='I',lb=0,ub=cap) for k in vehicles}; el={k:m.addVar(vtype='I',lb=0,ub=cap) for k in vehicles}
unmet={i:m.addVar(vtype='I',lb=0) for i in ids}
for k in vehicles:
    m.addCons(quicksum(x[k,start,j] for i,j in arcs if i==start)==1)
    m.addCons(quicksum(x[k,i,end] for i,j in arcs if j==end)==1)
    for q in ids:
        m.addCons(quicksum(x[k,i,j] for i,j in arcs if j==q)==y[k,q])
        m.addCons(quicksum(x[k,i,j] for i,j in arcs if i==q)==y[k,q])
        m.addCons(u[k,q]>=y[k,q]); m.addCons(u[k,q]<=n*y[k,q])
        m.addCons(p[k,q]<=cap*y[k,q]); m.addCons(d[k,q]<=cap*y[k,q])
    for i in ids:
      for j in ids:
       if i!=j: m.addCons(u[k,i]-u[k,j]+n*x[k,i,j]<=n-1)
    for i,j in arcs:
        if i==start and j in ids:
            change=p[k,j]-d[k,j]
            m.addCons(l[k,j]-sl[k]-change<=M*(1-x[k,i,j])); m.addCons(sl[k]+change-l[k,j]<=M*(1-x[k,i,j]))
        elif i in ids and j in ids:
            change=p[k,j]-d[k,j]
            m.addCons(l[k,j]-l[k,i]-change<=M*(1-x[k,i,j])); m.addCons(l[k,i]+change-l[k,j]<=M*(1-x[k,i,j]))
        elif i in ids and j==end:
            m.addCons(el[k]-l[k,i]<=M*(1-x[k,i,j]));m.addCons(l[k,i]-el[k]<=M*(1-x[k,i,j]))
for i in ids:
    s=byid[i]; P=quicksum(p[k,i] for k in vehicles); D=quicksum(d[k,i] for k in vehicles); target=s['net_rebalancing_target']
    m.addCons(s['initial_bikes']-P+D>=0);m.addCons(s['initial_bikes']-P+D<=s['station_capacity'])
    if target>=0: m.addCons(P+unmet[i]==target);m.addCons(D==0)
    else: m.addCons(D+unmet[i]==-target);m.addCons(P==0)
travel=quicksum(dist(i,j)*x[k,i,j] for k in vehicles for i,j in arcs)
m.setObjective(travel+data['penalty_weight']*quicksum(unmet.values()),'minimize');m.optimize()
if m.getNSols()==0: raise RuntimeError(m.getStatus())
def val(v): return int(round(m.getVal(v)))
vs=[]
for k in vehicles:
    nex={i:j for i,j in arcs if m.getVal(x[k,i,j])>.5}; route=[start]
    while route[-1]!=end: route.append(nex[route[-1]])
    vs.append({'vehicle_id':k,'start_load':float(val(sl[k])),'route':route,'stops':[{'station_id':i,'bikes_picked_up':float(val(p[k,i])),'bikes_dropped_off':float(val(d[k,i])),'load_after_stop':float(val(l[k,i]))} for i in route[1:-1]],'end_load':float(val(el[k]))})
ss=[]
for i in ids:
    P=sum(val(p[k,i]) for k in vehicles);D=sum(val(d[k,i]) for k in vehicles);net=P-D;t=byid[i]['net_rebalancing_target']
    ss.append({'station_id':i,'net_rebalancing_target':float(t),'total_bikes_picked_up':float(P),'total_bikes_dropped_off':float(D),'net_bike_change':float(net),'unmet_rebalancing_amount':float(abs(t-net))})
total=sum(s['unmet_rebalancing_amount'] for s in ss); tv=sum(dist(i,j) for k in vehicles for i,j in arcs if m.getVal(x[k,i,j])>.5)
report={'summary':{'objective':tv+data['penalty_weight']*total,'travel_distance_miles':tv,'unmet_rebalancing_penalty':data['penalty_weight']*total,'total_unmet_rebalancing_amount':total},'vehicles':vs,'stations':ss}
with open('/root/report.json','w') as f: json.dump(report,f,indent=2);f.write('\n')
print(json.dumps(report,indent=2))
